import {normalizeRecord} from './answer-revision.mjs';
import {questionnaireVersion} from './revised-data.mjs';
import {parts,surveyQuestions,surveyOrderVersion,partOf,partQuestionNumber,questionNumber,questionIndex,restoreQuestionIndex} from './survey-structure.mjs';
import {openImportDialog,openExportDialog} from './transfer-ui.mjs';
import {resultMarkup} from './result-view.mjs';
import {quickGuideMarkup} from './quick-guide.mjs';
import {data,profile,recommendedTypes,scorePair,demoAnswers,answeredCount,sanitizeAnswers,validAnswer,isSet} from './engine.mjs';
const total=surveyQuestions.length;
let demoIndex=1,demoVariant=0,imported=null,ownerPosition=null;
const app=document.getElementById('app'),key='suddenly-see-survey-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true,saved;
try{saved=JSON.parse(localStorage.getItem(key)||'null');}catch{saved=null;storageAvailable=false;}
const revised=normalizeRecord(saved);
let legacyArchive=revised.legacyArchive;
const currentAnswers=()=>imported?.answers??answers;
let completingPartner=!!saved?.completingPartner;
let answers=revised.answers,index=restoreQuestionIndex(saved),view=saved?.view==='part-intro'?'part-intro':['survey','result'].includes(saved?.view)&&answeredCount(answers)?saved.view:'home',demo=false,encountersOpen=false;
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 16v4h14v-4"/>'})[name]||''}</svg>`;
function flower(cls='brand-mark',petals=8){return `<svg class="${cls}" viewBox="0 0 200 200" fill="none" aria-hidden="true">${Array.from({length:petals},(_,i)=>`<ellipse cx="100" cy="64" rx="22" ry="45" fill="currentColor" fill-opacity=".35" transform="rotate(${i*360/petals} 100 100)"/>`).join('')}<circle cx="100" cy="100" r="13" fill="currentColor" fill-opacity=".55"/></svg>`;}
const mark=()=>`<svg class="brand-mark" viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M20 5v30M5 20h30M9.4 9.4l21.2 21.2M9.4 30.6 30.6 9.4" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><circle cx="20" cy="20" r="5" fill="var(--paper)" stroke="currentColor" stroke-width="1.5"/></svg>`;
function leaveImported(){if(!imported)return false;imported=null;if(ownerPosition){index=ownerPosition.index;view=ownerPosition.view;completingPartner=ownerPosition.completingPartner;}ownerPosition=null;return true;}
function persist(){if(demo||imported)return;try{localStorage.setItem(key,JSON.stringify({version:data.version,questionnaireVersion,legacyArchive,surveyOrder:surveyOrderVersion,questionId:surveyQuestions[index].id,completingPartner,answers,index,view}));storageAvailable=true;}catch{storageAvailable=false;}}
function header(extra=''){return `<header class="site-header"><button class="brand" data-action="home" aria-label="Suddenly I See 홈">${mark()}<span><span class="brand-name">Suddenly I See</span><span class="brand-sub">A LITTLE CLOSER TO YOU</span></span></button><div class="header-right">${extra}<span class="prototype ${view==='survey'?'hide-mobile':''}">EXPERIENCE 03</span></div></header>${!storageAvailable?'<div class="save-alert">이 브라우저에서 자동 저장을 사용할 수 없어요. 창을 닫기 전에 결과를 저장해 주세요.</div>':''}`;}
function research(){return `<details class="research-note"><summary>이 검사는 어떻게 만들어졌나요?</summary><p>사랑 태도, 친밀감과 헌신, 애착, 일반 성향 연구의 개념을 참고해 만든 자체 검사 초안이에요. 80개 문항과 16개 결과 유형, 추천 규칙은 팀의 설계이며 검증된 심리 진단이나 연애 성공 예측은 아니에요. 나와 관계를 이해하는 출발점으로 가볍게 읽어주세요.</p><p><a href="https://journals.sagepub.com/doi/abs/10.1177/0265407598152001" target="_blank" rel="noopener">사랑 태도 LAS</a> · <a href="https://link.springer.com/article/10.1007/s10508-023-02702-7" target="_blank" rel="noopener">TLS 15</a> · <a href="https://labs.psychology.illinois.edu/~rcfraley/measures/relstructures.htm" target="_blank" rel="noopener">ECR RS</a> · <a href="https://ipip.ori.org/" target="_blank" rel="noopener">IPIP</a></p></details>`;}
function footer(){return `${research()}<footer class="site-footer"><span class="footer-brand">Some connections begin with knowing yourself.</span><span>자체 검사 초안 · <a href="question-review.html" target="_blank" rel="noopener">80문항 검토 기준</a></span></footer>`;}
function showToast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2800);}
function changeView(next){view=next;persist();render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('main h1')?.focus({preventScroll:true});}
function render(){if(view==='home')renderHome();else if(view==='survey')renderSurvey();else if(view==='part-intro')renderPartIntro();else renderResult();}
function renderHome(){const count=answeredCount(answers);app.innerHTML=`${header()}<main id="main" class="page fade-in"><section class="hero"><div><div class="eyebrow">THE WAY YOU LOVE</div><h1 tabindex="-1">당신의 마음은,<br>어떤 <em>모양</em>인가요?</h1><p class="hero-copy">마음을 표현하는 방식부터 함께하고 싶은 일상까지.<br>${total}개의 질문을 따라,<br>나와 닮은 관계의 모양을 만나보세요.</p>${count?`<div class="saved-badge">${icon('check')} ${count}개의 답변이 기다리고 있어요</div>`:''}<div class="hero-actions"><button class="button primary" data-action="start">${count===total?'내 결과 다시 보기':count?'이어서 알아보기':'나의 마음 알아보기'} ${icon('arrow')}</button><button class="button secondary" data-action="demo">예시 결과 먼저 보기</button><button class="button secondary" data-action="import">기존 결과 불러오기</button></div><p class="hero-note">${icon('lock')}답변은 서버로 전송하지 않고, 이 브라우저에만 저장해요.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit-outer"></div><div class="orbit-inner"></div><div class="orb"></div>${flower('petal-art')}<div class="orbit-dot dot-one"></div><div class="orbit-dot dot-two"></div><span class="art-tag">EVERY HEART HAS ITS OWN SHAPE</span><span class="floating-label label-one">나답게 사랑하는 방법</span><span class="floating-label label-two">조금씩, 가까이</span><span class="art-word">a little closer,<br>to you.</span></div></section><section class="intro-strip" aria-label="검사 구성"><div class="intro-item"><span class="intro-number">${total}</span><div><strong>나를 알아가는 질문</strong><small>나의 모습부터 일상까지</small></div></div><div class="intro-item"><span class="intro-number">12</span><div><strong>마음의 여러 면</strong><small>한 가지로 정하지 않는 나</small></div></div><div class="intro-item"><span class="intro-number">16</span><div><strong>관계의 모양</strong><small>같은 유형도 서로 다른 결</small></div></div></section><section class="survey-parts" aria-label="설문 두 파트">${parts.map((p,g)=>`<article><span class="eyebrow">PART 0${g+1}</span><h2>${p.name}</h2><p>${p.description}</p><small>${p.ids.length}문항 · ${g===0?'나의 관계 방식 48 + 생활 리듬 9':'상대 성향 12 + 생활 선호 9 + 종합 기준 2'}</small></article>`).join('')}</section>${quickGuideMarkup()}<div class="home-bottom"><p>정답은 없어요. 지금의 나에게 가까운 답을 골라주세요.<br>언제든 멈추고, 다시 이어갈 수 있어요.</p><span class="subtle-caps">YOUR OWN PACE. YOUR OWN CONNECTION.</span></div></main>${footer()}`;}
function renderPartIntro(){const answers=currentAnswers();const g=partOf(surveyQuestions[index].id),part=parts[g];app.innerHTML=header('<button class="link-button" data-action="home">잠시 나가기</button>')+'<main id="main" class="part-intro page fade-in"><section class="part-intro-card"><div class="eyebrow">PART 0'+(g+1)+' / 02</div><h1 tabindex="-1">'+part.title+'</h1><p class="part-lead">'+part.description+'</p><div class="part-focus"><strong>'+part.name+' · '+part.ids.length+'문항</strong><p>'+part.hint+'</p><p>'+part.role+'</p></div>'+(g===1?'<p class="caption">파트 1: '+parts[0].ids.filter(id=>validAnswer(id,answers[id])).length+' / '+parts[0].ids.length+'개 답변 · 다음은 상대에게 바라는 모습이에요.</p>':'<p class="caption">나를 알아본 다음, 파트 2에서 원하는 상대를 따로 살펴요.</p>')+'<div class="part-intro-actions"><button class="button primary" data-action="part-start">파트 '+(g+1)+' 시작하기 '+icon('arrow')+'</button><button class="link-button" data-action="part-back">'+(g===0?'처음 화면':'파트 1 마지막 질문으로')+'</button></div></section></main>'+footer();}
const groupOf=partOf;
const groupNames=parts.map(p=>p.name);
const descriptions=parts.map(p=>p.hint);
function option(id,value,text,kind,checked,number=null){const encoded=typeof value==='number'?String(value):value;return `<label class="option"><input type="${kind==='multi'?'checkbox':'radio'}" id="choice-${id}-${encoded}" name="q${id}" data-question="${id}" data-value="${encoded}" ${checked?'checked':''}><span class="option-box">${number!==null?`<span class="option-number">${number}</span><span class="option-text">${esc(text)}</span>`:kind==='single'?`<span class="radio-dot"></span><span>${esc(text)}</span>`:esc(text)}</span></label>`;}
function unknownOption(id,label){const answers=currentAnswers();return `<label class="unknown-option"><input type="radio" id="choice-${id}-unknown" name="q${id}" data-question="${id}" data-value="unknown" ${answers[id]==='unknown'?'checked':''}><span>${esc(label)}</span></label>`;}
function questionOptions(q){const answers=currentAnswers();const id=q.id,a=answers[id];
 if(id<=48)return `<div class="likert">${['전혀 그렇지 않다','그렇지 않은 편','중간 정도','그런 편','매우 그렇다'].map((t,i)=>option(id,i+1,t,'single',a===i+1,i+1)).join('')}</div>${unknownOption(id,'잘 모르겠어요 · 판단할 경험이 없어요')}`;
 if(id===115)return '<div class="chip-options">'+q.options.map((t,i)=>option(id,i,t,'multi',isSet(a)&&a.includes(i))).join('')+'</div><div class="choice-list" style="margin-top:12px">'+option(id,'none','특히 우선하는 영역 없이 고르게 볼게요','single',a==='none')+'</div>'+unknownOption(id,'아직 우선순위를 모르겠어요');
 if(id>=73){
  const multi=q.kind==='partner-life',values=q.values??q.options.map((_,i)=>i);
  return '<div class="'+(multi?'chip-options':'choice-list')+'">'+q.options.map((t,i)=>option(id,values[i],t,multi?'multi':'single',multi?isSet(a)&&a.includes(values[i]):a===values[i])).join('')+((q.allowAny||multi)?option(id,'any','어느 쪽이든 괜찮아요','single',a==='any'):'')+'</div>'+unknownOption(id,'아직 잘 모르겠어요');
 }
 if(id>=61)return `<div class="choice-list">${q.options.map((t,i)=>option(id,['low','mid','high'][i],t,'single',a===['low','mid','high'][i])).join('')}${option(id,'any','어느 쪽이든 괜찮아요','single',a==='any')}</div>${unknownOption(id,'아직 잘 모르겠어요')}`;
 if(id===51){const days=['월','화','수','목','금','토','일'];return `<div class="calendar" role="group" aria-label="편한 요일과 시간"><span></span>${days.map(d=>`<span class="calendar-header">${d}</span>`).join('')}${['낮','저녁'].map((time,ti)=>`<span class="calendar-row">${time}<br>${ti?'18~23':'10~18'}시</span>${days.map((day,di)=>`<label class="option"><input type="checkbox" id="choice-51-${di*2+ti}" name="q51" data-question="51" data-value="${di*2+ti}" aria-label="${day}요일 ${time}" ${isSet(a)&&a.includes(di*2+ti)?'checked':''}><span class="option-box">${isSet(a)&&a.includes(di*2+ti)?'✓':'·'}</span></label>`).join('')}`).join('')}</div><p class="calendar-help">여러 칸을 고를 수 있어요. 보통 만날 수 있는 시간을 골라주세요.</p>${unknownOption(id,'일정이 불규칙해서 아직 모르겠어요')}`;}
 const multi=[52,56,58,60].includes(id);
 let html=`<div class="${multi?'chip-options':'choice-list'}">${data.lifeOptions[id].map((t,i)=>option(id,i,t,multi?'multi':'single',multi?isSet(a)&&a.includes(i):a===i)).join('')}</div>`;
 if([56,58,60].includes(id))html+=`<div class="choice-list" style="margin-top:12px">${option(id,'any','어느 범위든 괜찮아요','single',a==='any')}</div>`;
 html+=unknownOption(id,id===52?'특별히 정한 활동이 없어요':[54,55,57].includes(id)?'응답하지 않을게요':'아직 잘 모르겠어요');
 return html;
}
function renderSurvey(focusId=null){const answers=currentAnswers();const q=surveyQuestions[index],id=q.id,g=groupOf(id),count=answeredCount(answers),selected=validAnswer(id,answers[id]);
 const help=q.help??(id===52?`평소 즐기는 활동을 최대 5개 골라주세요. (${isSet(answers[id])?answers[id].length:0}/5)`:[56,58,60].includes(id)?'편하게 느끼는 범위를 여러 개 고를 수 있어요.':id===54?'특별한 기념일을 제외하고, 내가 부담하기 편한 금액을 생각해 주세요.':id<=48?'평소의 나와 얼마나 가까운가요?':descriptions[g]);
 app.innerHTML=`${header(`<button class="link-button" data-action="home">잠시 나가기</button>`)}<div class="survey-top"><div class="survey-top-inner"><span>PART ${g+1} · ${parts[g].short}</span><span class="progress-label">${count} / ${total} 답변</span><button class="link-button" data-action="navigator">${icon('grid')} 전체 문항</button></div><div class="progress-track" role="progressbar" aria-label="설문 진행률" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${total}"><div class="progress-fill" style="width:${count/total*100}%"></div></div></div><main id="main" class="survey-shell"><aside class="survey-aside">${groupNames.map((name,i)=>`<div class="section-step ${g===i?'active':parts[i].ids.every(id=>validAnswer(id,answers[id]))?'done':''}"><span class="step-num">${g!==i&&parts[i].ids.every(id=>validAnswer(id,answers[id]))?'✓':`0${i+1}`}</span><span class="step-caption">${name}<small>${parts[i].ids.length}문항 · ${parts[i].ids.filter(id=>validAnswer(id,answers[id])).length}개 답변</small></span></div>`).join('')}<div class="aside-note">누군가에게 맞추기보다,<br>각 파트의 대상을<br>떠올리며 답해 주세요.<br>${flower('tiny-flower')}</div></aside><section class="question-card"><div class="part-context"><strong>PART ${g+1} · ${groupNames[g]}</strong><span>${g===0?'평소의 나를 떠올려 주세요.':'상대에게 바라는 모습을 골라주세요.'} ${partQuestionNumber(id)} / ${parts[g].ids.length}</span></div><div class="question-meta"><span class="question-number">${String(index+1).padStart(2,'0')}</span><span class="separator"></span><span>${id<=48?data.domains[Math.floor((id-1)/4)].name:groupNames[g]}</span></div><h1 id="question-heading" tabindex="-1">${esc(q.text)}</h1><div class="question-help">${esc(help)}${completingPartner?' · 현재 설문에서 아직 답하지 않은 질문만 보고 있어요.':''}</div><fieldset class="question-options"><legend class="sr-only">${esc(q.text)}</legend>${questionOptions(q)}</fieldset><div class="question-footer"><button class="previous" data-action="previous" ${index===0?'disabled':''}>${icon('arrow')} 이전</button><button class="button primary" data-action="next" ${!selected?'disabled':''}>${index===total-1?'내 결과 만나보기':index===parts[0].ids.length-1?'파트 2로 이동':'다음 질문'} ${icon('arrow')}</button></div><div class="save-status">${imported?'불러온 응답을 이 화면에서만 수정해요. 닫기 전에 결과를 저장해 주세요.':storageAvailable?'선택한 답변은 자동으로 저장돼요.':'이 브라우저에서 저장이 제한되어 있어요.'}${count===total?' · <button class="link-button" data-action="result">수정한 결과 보기</button>':''}</div></section></main>${footer()}`;
 if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
}
function preferenceLabel(a,i){const v=a[61+i];return v==='any'?'어느 쪽이든 괜찮아요':v==='unknown'||!v?'아직 알아가는 중':data.questions[60+i].options[['low','mid','high'].indexOf(v)];}
function lifeLabel(a,id){return typeof a[id]==='number'?data.lifeOptions[id]?.[a[id]]:'아직 알아가는 중';}
function traitMarkup(p){return `<div class="trait-grid">${data.domains.map((d,i)=>`<div class="trait-row"><div class="trait-head"><span>${d.name}</span><span class="trait-value">${p.scores[i]===null?'미측정':p.scores[i]}</span></div><div class="trait-track"><div class="trait-fill" style="width:${p.scores[i]??0}%"></div></div><div class="trait-ends"><span>${d.low}</span><span>${d.high}</span></div></div>`).join('')}</div><p class="caption">숫자는 응답을 0~100으로 정리한 값이에요. 높고 낮음의 우열이나 다른 사람과의 순위를 뜻하지 않아요. ‘미측정’은 판단 가능한 답변이 부족한 영역이에요.</p>`;}
function lifeMarkup(a){const slots=isSet(a[51])?a[51].map(i=>`${['월','화','수','목','금','토','일'][Math.floor(i/2)]} ${i%2?'저녁':'낮'}`):[];
 const cards=[['편안한 연락',lifeLabel(a,49)],['만남의 빈도',lifeLabel(a,50)],['데이트 활동량',lifeLabel(a,53)],['데이트 한 번의 내 부담액',lifeLabel(a,54)],['나의 흡연 습관',lifeLabel(a,55)],['한 달 음주일',lifeLabel(a,57)]];
 return `<div class="life-grid">${cards.map(([l,v])=>`<div class="life-card"><div class="label">${l}</div><div class="value">${esc(v)}</div></div>`).join('')}<div class="life-card wide"><div class="label">내가 평소 즐기는 활동</div><div class="tiny-tags">${isSet(a[52])?a[52].map(i=>`<span class="tiny-tag">${data.lifeOptions[52][i]}</span>`).join(''):'<span class="value">아직 정하지 않았어요</span>'}</div></div><div class="life-card"><div class="label">지금 알아가고 싶은 관계</div><div class="value">${esc(lifeLabel(a,59))}</div></div><div class="life-card wide"><div class="label">만남을 잡기 편한 시간</div><div class="tiny-tags">${slots.length?slots.map(s=>`<span class="tiny-tag">${s}</span>`).join(''):'<span class="value">아직 알아가는 중</span>'}</div></div><div class="life-card"><div class="label">상대의 생활에서 편한 범위</div><div class="value">${[56,58,60].map((id,i)=>`${['흡연','음주','관계 방향'][i]}: ${a[id]==='any'?'상관없음':isSet(a[id])?a[id].map(n=>data.lifeOptions[id][n]).join(', '):'미정'}`).map(esc).join('<br>')}</div></div></div>`;
}
function renderResult(){app.innerHTML=resultMarkup({answers:imported?.answers??answers,legacyArchive:imported?imported.legacyArchive:legacyArchive,imported,demo,demoIndex,demoVariant,encountersOpen,header,footer,flower,icon,traitMarkup,lifeMarkup});}
function navigateQuestion(id){demo=false;index=questionIndex(id);changeView('survey');}
function navigator(){const answers=currentAnswers();const dialog=document.createElement('dialog');dialog.className='nav-dialog';dialog.innerHTML='<div class="dialog-header"><h2>답변 돌아보기</h2><button class="dialog-close" data-action="close-dialog" aria-label="닫기">'+icon('close')+'</button></div><p>파트별로 질문을 확인해요. 분홍색은 답변한 질문이에요.</p>'+parts.map((part,g)=>'<section class="navigator-part"><h3>PART '+(g+1)+' · '+part.name+'</h3><p>'+part.ids.filter(id=>validAnswer(id,answers[id])).length+' / '+part.ids.length+' 답변</p><div class="question-grid">'+part.ids.map(id=>'<button class="question-jump '+(validAnswer(id,answers[id])?'filled':'')+' '+(surveyQuestions[index].id===id?'current':'')+'" data-go="'+id+'" aria-label="파트 '+(g+1)+' · '+questionNumber(id)+'번 질문'+(validAnswer(id,answers[id])?', 답변 완료':'')+'">'+questionNumber(id)+'</button>').join('')+'</div></section>').join('');document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
function resetDialog(){const dialog=document.createElement('dialog');dialog.className='nav-dialog';dialog.innerHTML=`<div class="dialog-header"><h2>처음부터 다시 알아볼까요?</h2></div><p>이 브라우저에 저장된 답변과 결과를 지우고 새로 시작해요.</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">답변 유지하기</button><button class="button primary" data-action="confirm-reset">지우고 시작하기</button></div>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
document.addEventListener('change',event=>{const input=event.target.closest('input[data-question]');if(!input)return;const answers=currentAnswers();const id=Number(input.dataset.question),value=/^\d+$/.test(input.dataset.value)?Number(input.dataset.value):input.dataset.value;
 if(input.type==='checkbox'){const set=new Set(isSet(answers[id])?answers[id]:[]);if(input.checked)set.add(value);else set.delete(value);if(id===115&&set.size>3){input.checked=false;showToast('특히 중요한 성향은 최대 3개까지 골라주세요.');return;}if(id===52&&set.size>5){input.checked=false;showToast('활동은 최대 5개까지 고를 수 있어요.');return;}if(set.size)answers[id]=[...set].sort((a,b)=>a-b);else delete answers[id];}else answers[id]=value;
 persist();renderSurvey(input.id);
});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;const activeAnswers=currentAnswers();
 if(button.dataset.demoType!==undefined){demoIndex=Number(button.dataset.demoType);demoVariant=0;demo=true;encountersOpen=false;changeView('result');return;}
 if(button.dataset.go){completingPartner=false;document.querySelector('dialog')?.close();navigateQuestion(Number(button.dataset.go));return;}
 const action=button.dataset.action;
 if(action==='complete-partner'){completingPartner=true;const missing=surveyQuestions.find(q=>!validAnswer(q.id,activeAnswers[q.id]));if(missing)navigateQuestion(missing.id);return;}
 if(action==='part-start'){changeView('survey');return;}
 if(action==='part-back'){if(partOf(surveyQuestions[index].id)===1){index=parts[0].ids.length-1;changeView('survey');}else changeView('home');return;}
 if(action==='import'){openImportDialog(result=>{if(!imported)ownerPosition={index,view,completingPartner};imported=result;demo=false;encountersOpen=false;changeView('result');});return;}
 if(action==='return-own'){leaveImported();demo=false;encountersOpen=false;render();window.scrollTo(0,0);return;}
 if(action==='demo-variant'){demoVariant=demoVariant?0:1;renderResult();return;}
 if(action==='home'){const wasImported=leaveImported();demo=false;if(wasImported){view='home';render();window.scrollTo(0,0);}else changeView('home');}
 if(action==='start'){leaveImported();demo=false;if(answeredCount(answers)===0){index=0;changeView('part-intro');return;}if(answeredCount(answers)===total)changeView('result');else{if(!validAnswer(surveyQuestions[index].id,answers[surveyQuestions[index].id])){}else{const missing=surveyQuestions.find(q=>!validAnswer(q.id,answers[q.id]));index=missing?questionIndex(missing.id):index;}changeView('survey');}}
 if(action==='start-own'){leaveImported();demo=false;if(answeredCount(answers)===0){index=0;changeView('part-intro');return;}const missing=surveyQuestions.find(q=>!validAnswer(q.id,answers[q.id]));index=missing?questionIndex(missing.id):0;changeView('survey');}
 if(action==='demo'){leaveImported();demo=true;encountersOpen=false;changeView('result');}
 if(action==='previous'&&index>0){index--;changeView('survey');}
 if(action==='next'){const answers=activeAnswers;if(!validAnswer(surveyQuestions[index].id,answers[surveyQuestions[index].id]))return;if(completingPartner){const missing=surveyQuestions.find(q=>!validAnswer(q.id,answers[q.id]));if(missing)navigateQuestion(missing.id);else{completingPartner=false;changeView('result');}return;}if(index<total-1){const previousPart=partOf(surveyQuestions[index].id);index++;changeView(partOf(surveyQuestions[index].id)!==previousPart?'part-intro':'survey');}else{const missing=surveyQuestions.find(q=>!validAnswer(q.id,answers[q.id]));if(missing){showToast('아직 답하지 않은 질문으로 돌아갈게요.');navigateQuestion(missing.id);}else{encountersOpen=false;changeView('result');}}}
 if(action==='result'){encountersOpen=false;changeView('result');}
 if(action==='edit'){navigateQuestion(1);navigator();}
 if(action==='navigator')navigator();
 if(action==='close-dialog')button.closest('dialog')?.close();
 if(action==='reset')resetDialog();
 if(action==='confirm-reset'){button.closest('dialog')?.close();answers={};legacyArchive=null;index=0;completingPartner=false;demo=false;encountersOpen=false;changeView('part-intro');}
 if(action==='encounters'){const y=window.scrollY;encountersOpen=!encountersOpen;renderResult();window.scrollTo({top:y,behavior:'instant'});}
 if(action==='download'){openExportDialog(imported?.answers??answers,{imported:!!imported,legacyArchive:imported?imported.legacyArchive:legacyArchive});return;}
});
if(location.hash==='#reading-changes')history.replaceState(null,'',location.pathname+location.search);
render();
